class Solution:
    def popcountDepth(self, n, k):
        from math import comb
        d = [0] * 60
        for c in range(2, 60):
            d[c] = 1 + d[bin(c).count('1')]
        def cnt(m, c):
            if c < 0 or c > 60: return 0
            res = 0; ones = 0
            for i in range(59, -1, -1):
                if (m >> i) & 1:
                    need = c - ones
                    if 0 <= need <= i: res += comb(i, need)
                    ones += 1
            if ones == c: res += 1
            return res
        if k == 0: return 1
        ans = 0
        for c in range(1, 60):
            if 1 + d[c] == k:
                ans += cnt(n, c)
        if k == 1: ans -= 1
        return ans

