class Solution {
public:
    long long popcountDepth(long long n, int k) {
        int d[60] = {0};
        for (int c = 2; c < 60; c++) d[c] = 1 + d[__builtin_popcountll(c)];
        auto cnt = [&](long long m, int c) -> long long {
            if (c < 0 || c > 60) return 0;
            long long res = 0; int ones = 0;
            for (int i = 59; i >= 0; i--) if ((m >> i) & 1) {
                int need = c - ones;
                if (need >= 0 && need <= i) { long long r = 1; for (int j = 0; j < need; j++) r = r * (i - j) / (j + 1); res += r; }
                ones++;
            }
            if (ones == c) res++;
            return res;
        };
        if (k == 0) return 1;
        long long ans = 0;
        for (int c = 1; c < 60; c++) if (1 + d[c] == k) ans += cnt(n, c);
        if (k == 1) ans--;
        return ans;
    }
};

