        int[] d = new int[60];
        for (int c = 2; c < 60; c++) d[c] = 1 + d[Long.bitCount(c)];
        class H { long cnt(long m, int c) {
            if (c < 0 || c > 60) return 0;
            long res = 0; int ones = 0;
            for (int i = 59; i >= 0; i--) if (((m >> i) & 1) == 1) {
                int need = c - ones;
                if (need >= 0 && need <= i) { long r = 1; for (int j = 0; j < need; j++) r = r * (i - j) / (j + 1); res += r; }
                ones++;
            }
            if (ones == c) res++;
            return res;
        }}
        H h = new H();
