var popcountDepth = function(n, k) {
    const bc = (x) => { let r = 0; while (x) { r += x & 1; x >>= 1; } return r; };
    const d = new Array(60).fill(0);
    for (let c = 2; c < 60; c++) d[c] = 1 + d[bc(c)];
    const comb = (a, b) => { if (b < 0 || b > a) return 0; let r = 1; for (let j = 0; j < b; j++) r = r * (a - j) / (j + 1); return Math.round(r); };
    const cnt = (m, c) => {
        let res = 0, ones = 0;
        for (let i = 59; i >= 0; i--) if ((Number(m) >> i) & 1) { const need = c - ones; if (need >= 0 && need <= i) res += comb(i, need); ones++; }
        if (ones === c) res++;
        return res;
    };
    if (k === 0) return 1;
    let ans = 0;
    for (let c = 1; c < 60; c++) if (1 + d[c] === k) ans += cnt(BigInt(n), c);
    if (k === 1) ans -= 1;
    return ans;
};
